WITH metrics AS (SELECT *, MIN(discount_pct) OVER (PARTITION BY promo_code) AS promo_code_min_discount_pct, NTILE(5) OVER (PARTITION BY promo_code, channel ORDER BY discount_pct, id) AS discount_pct_bucket, NTILE(5) OVER (PARTITION BY promo_code ORDER BY discount_pct DESC, id) AS discount_pct_bucket_2 FROM promotions) SELECT id, channel, promo_code, starts_on, discount_pct, promo_code_min_discount_pct, discount_pct_bucket, discount_pct_bucket_2, CASE WHEN channel RLIKE '^(partner|web)$' THEN 'EXTENDED' ELSE 'PRIORITY' END AS channel_zone FROM metrics ORDER BY promo_code_min_discount_pct DESC NULLS LAST;
